const http = require('http');
const pagina = '<!doctype html><html lang="es"><head><meta charset="utf-8">' +
  '<link rel="stylesheet" href="/estilo.css"></head><body><h1>Rutas de hoy</h1>' +
  '<img src="/logo.svg" width="64" height="64" alt="logo"><ul id="rutas"></ul>' +
  '<script src="/app.js"></script></body></html>';

const manejador = (req, res) => {
  const enviar = (tipo, cuerpo, extra = {}, demora = 0) => setTimeout(() => {
    res.writeHead(200, { 'Content-Type': tipo, 'Content-Length': Buffer.byteLength(cuerpo), ...extra });
    res.end(cuerpo);
  }, demora);
  const ruta = req.url.split('?')[0];
  if (ruta === '/')            return enviar('text/html; charset=utf-8', pagina, { 'Cache-Control': 'no-cache' }, 30);
  if (ruta === '/estilo.css')  return enviar('text/css', 'body{margin:2rem}', { 'Cache-Control': 'max-age=3600' }, 10);
  if (ruta === '/api/rutas')   return enviar('application/json', '["Barracas-Córdoba"]', { 'Cache-Control': 'no-store' }, 120);
  if (ruta === '/lento')       return enviar('text/plain', 'respuesta tardía\n', {}, 300);
  if (ruta === '/hola')        return enviar('text/plain; charset=utf-8', 'hola desde el laboratorio\n');
  res.writeHead(404); res.end('no existe\n');
};
http.createServer(manejador).listen(18529, '127.0.0.1');

const net = require('net');
const [escucha, destino, demora] = process.argv.slice(2).map(Number);
net.createServer((cliente) => {
  const servidor = net.connect(destino, '127.0.0.1');
  const pasar = (de, a) => de.on('data', (trozo) => setTimeout(() => a.write(trozo), demora));
  pasar(cliente, servidor);
  pasar(servidor, cliente);
}).listen(escucha, '127.0.0.1');

