// Convierte los tiempos ACUMULADOS que imprime curl -w (en segundos) en lo que tardó cada fase (en milisegundos).
function fases(t) {
  const ms = (x) => Math.round(x * 10000) / 10;
  const hayTls = t.appconnect > 0;
  const antesDelPedido = hayTls ? t.appconnect : t.connect;
  return {
    dns: ms(t.namelookup),
    tcp: ms(t.connect - t.namelookup),
    tls: hayTls ? ms(t.appconnect - t.connect) : 0,
    espera: ms(t.starttransfer - antesDelPedido),
    descarga: ms(t.total - t.starttransfer),
  };
}

function veredicto(f) {
  const mayor = Object.entries(f).sort((a, b) => b[1] - a[1])[0];
  const lectura = { dns: 'resolver el nombre', tcp: 'abrir la conexión', tls: 'negociar TLS',
    espera: 'esperar al servidor (distancia o cómputo)', descarga: 'bajar el cuerpo (ancho de banda)' };
  return `${mayor[0]} = ${mayor[1]} ms → lo que más pesa es ${lectura[mayor[0]]}`;
}

